  "privRetention": "Bewaren en verwijderen",
  "privRights": "Je rechten",
  "noticeReopen": "Opslagmelding",
  "noticeLabel": "Melding over browseropslag",
  "noticeText": "Cook gebruikt browseropslag voor de kook- en inlogfuncties die je gebruikt. Er wordt geen opslag voor advertenties of analyse toegevoegd.",
  "noticeClose": "Opslagmelding sluiten",
  "privDraftLabel": "Concept — bijgewerkt op 28 oktober 2026.",
  "privDraft": "De accountfuncties worden momenteel getest. De gegevens over de exploitant en de diensten hieronder moeten vóór de publieke lancering worden aangevuld.",
  "privWho1": "Cook wordt geëxploiteerd door [officiële naam en postadres van de exploitant]. Neem voor vragen en verzoeken over privacy contact op via [e-mailadres voor privacy]. Deze gegevens moeten worden aangevuld voordat registratie opengaat.",
  "privWhat1": "Als je een account aanmaakt, gebruiken we je e-mailadres, een accountnummer, gegevens over wachtwoordauthenticatie en de verificatiestatus om je account te leveren en te beveiligen. Wachtwoorden worden door de authenticatieprovider als veilige hashes verwerkt; Cook bewaart geen leesbare wachtwoorden. We bewaren je keukenindeling, gekozen taal, thema en maateenheden om je instellingen op al je apparaten te herstellen. Een e-mailadres en wachtwoord zijn nodig voor een account; recepten bekijken kan ook zonder.",
  "privWhat2": "Verwerking van account- en instellingsgegevens is nodig om de accountdienst te leveren die je vraagt (artikel 6, lid 1, onder b, AVG). Beperkte gegevens voor beveiliging en misbruikpreventie kunnen op basis van gerechtvaardigd belang worden verwerkt (artikel 6, lid 1, onder f), voor zover noodzakelijk en na belangenafweging. Verificatie- en wachtwoordherstelmails zijn servicemeldingen, geen marketing. De accountfunctie voegt geen advertenties of analyse toe.",
  "privStorage1": "Cook gebruikt sessionStorage om je keuken, kookvoortgang en keuzes mee te nemen tussen pagina’s in hetzelfde tabblad. Als je bent ingelogd, bevat het ook je inlogsessie. De browser wist dit normaal gesproken als de tabbladsessie eindigt, maar sessieherstel van de browser kan het bewaren. Uitloggen wist de tabbladgegevens van Cook. Het sluiten van de opslagmelding wordt alleen in dat tabblad bewaard. De eigen scripts van Cook plaatsen geen cookies. Je hosting- of dienstverleners kunnen eigen beveiligingsverwerkingen hebben die vóór de lancering moeten worden gedocumenteerd.",
  "privStorage2": "OK en de sluitknop van de opslagmelding sluiten alleen de melding. Ze geven geen toestemming voor analyse, advertenties of ander optioneel volgen. Toekomstige niet-noodzakelijke opslag vereist vooraf een aparte keuze, met even eenvoudig weigeren en intrekken.",
  "privOther1": "De huidige spraakfunctie van de receptenlijst vraagt bij country.is op basis van je IP-adres een benaderd land op om een spraaktaal te kiezen. Als je microfoonherkenning gebruikt, kan je browser audio naar zijn spraakdienst sturen. Je kunt ingrediënten ook typen. Deze aanbieders, hun beleid en de rechtsgrond van deze functies moeten vóór de publieke lancering worden beoordeeld.",
  "privProviders1": "Geplande accountprovider: Supabase (beheerde PostgreSQL en authenticatie), met een gekozen databaseregio in de EU. E-mailprovider: [aanbieder]. Websitehosting: [aanbieder]. De exploitant moet de werkelijke aanbieders, verwerkersovereenkomsten, subverwerkers, locaties van logbestanden en eventuele doorgifte buiten de EER bevestigen. Een databaseregio in de EU sluit internationale doorgifte op zich niet uit. Vermeld waar van toepassing het geldende adequaatheidsbesluit of de contractuele waarborgen en hoe je een kopie kunt krijgen.",
  "privRetention1": "Accountinstellingen worden bewaard zolang je account actief is. Je kunt verwijdering aanvragen via het privacycontact hierboven. Vóór de lancering moet de exploitant vastleggen hoe verwijderverzoeken worden afgehandeld, wanneer niet-geverifieerde accounts vervallen en hoe lang beveiligingslogs en back-ups worden bewaard. Verwijderde gegevens kunnen in afgeschermde back-ups blijven tot de vastgelegde bewaartermijn afloopt.",
  "privRights1": "Afhankelijk van de geldende voorwaarden kun je om inzage, correctie, verwijdering, beperking of overdraagbaarheid vragen, of bezwaar maken tegen verwerking op basis van gerechtvaardigd belang. Neem contact op met de exploitant hierboven; verzoeken worden normaal binnen een maand beantwoord, met uitleg bij een wettelijke verlenging. Je kunt een klacht indienen bij je toezichthouder, waaronder de Hongaarse NAIH via naih.hu. Cook gebruikt accountinstellingen niet voor geautomatiseerde besluiten met rechtsgevolgen of vergelijkbaar ingrijpende gevolgen.",
